import fs from 'node:fs';
import {stripTypeScriptTypes} from 'node:module';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const path=process.argv[1];
const source=fs.readFileSync(path,'utf8');
const output=stripTypeScriptTypes(source,{mode:'transform',sourceUrl:path});
const parsed=spawnSync(process.execPath,['--input-type=module','--check'],{input:output,encoding:'utf8'});
console.log(JSON.stringify({status:parsed.status===0?'PASS_SYNTAX_ONLY':'FAIL',node:process.version,sourcePath:path,sourceSha256:createHash('sha256').update(source).digest('hex'),transformedBytes:Buffer.byteLength(output),parserCommand:[process.execPath,'--input-type=module','--check'],parserExitCode:parsed.status,parserStdout:parsed.stdout,parserStderr:parsed.stderr,importResolutionRun:false,typeCheckerInvoked:false,businessRunnerInvoked:false,pgInvoked:false},null,2));
process.exitCode=parsed.status??1;
